function GuideBreadcrumb({onBack,onHome,label,title}:{onBack:()=>void,onHome?:()=>void,label:string,title:string}){return <div className="guideBreadcrumb"><div className="guideNavButtons"><button type="button" onClick={onBack}><span>←</span>{label}</button>{onHome&&<button type="button" className="guideHomeButton" onClick={onHome}><span>⌂</span>タスクTOPへ戻る</button>}</div><div className="guideCurrent"><small>CURRENT PAGE</small><strong>{title}</strong></div></div>}
